101:     fn increment_depth(&mut self, limits: &YamlLimits) -> YamlResult<()> {
102:         self.depth = self.depth.checked_add(1).ok_or(YamlError::NestingTooDeep {
103:             depth: self.depth,
104:             max: limits.max_depth,
105:         })?;
106:         if self.depth > limits.max_depth {
107:             return Err(YamlError::NestingTooDeep {
108:                 depth: self.depth,
109:                 max: limits.max_depth,
110:             });
111:         }
