115:     fn record_scalar(&mut self, value: &str, limits: &YamlLimits) -> YamlResult<()> {
116:         check_scalar_length(value, limits.max_scalar_bytes)?;
117:         check_null_bytes(value)?;
118:         if let Some(&true) = self.in_mapping.last() {
119:             self.record_mapping_scalar(limits)?;
120:         } else if self.in_mapping.last().is_some() {
121:             self.record_sequence_scalar(limits)?;
122:         }
123:         self.found_content = true;
124:         Ok(())
125:     }
