127:     fn record_mapping_scalar(&mut self, limits: &YamlLimits) -> YamlResult<()> {
128:         if self.expecting_key.last() == Some(&true) {
129:             if let Some(counter) = self.map_counters.last_mut() {
130:                 *counter = counter.checked_add(1).ok_or(YamlError::NodeLimitExceeded {
131:                     count: u32::MAX,
132:                     max: limits.max_nodes,
133:                 })?;
134:                 if *counter > limits.max_mapping_entries {
135:                     return Err(YamlError::MappingTooLarge {
