137:                         max: limits.max_mapping_entries,
138:                     });
139:                 }
140:             }
141:             if let Some(expecting) = self.expecting_key.last_mut() {
142:                 *expecting = false;
143:             }
144:         } else if let Some(expecting) = self.expecting_key.last_mut() {
145:             *expecting = true;
146:         }
147:         Ok(())
148:     }
